fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    if len <= 1 {
        // For empty or single-element array, return (a, empty) 
        // which satisfies all conditions:
        // concatenation is original a,
        // sums to length,
        // and no strict shorter arrays required since len <= 1.
        (a, Vec::new())
    } else {
        // For length > 1, split roughly in half
        // ensuring each part is strictly shorter than original.
        let mid = len / 2;
        let left = a[..mid].to_vec();
        let right = a[mid..].to_vec();
        (left, right)
    }
}